package dev.cazajefes;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class DuelRulesTest {
 @Test public void eightRelicsUseUniqueMaterialsAndExpectedMenuRoutes(){assertEquals(8,DuelCatalog.ALL.size());Set<String> ids=new HashSet<>(),materials=new HashSet<>();int armor=0,weapons=0;for(var r:DuelCatalog.ALL){assertTrue(ids.add(r.id()));assertTrue(materials.add(r.material()));assertNotNull(r.gear());assertNotNull(r.reagent());assertTrue(r.cooldown()>=10000);assertTrue(r.cooldown()<=18000);if(r.armor())armor++;else weapons++;assertEquals(RaresMenu.Category.PVP,RaresMenu.Category.category("pvp_gear_"+r.id()));assertEquals(RaresMenu.Category.MATERIALS,RaresMenu.Category.category("pvp_material_"+r.id()));}assertEquals(4,armor);assertEquals(4,weapons);}
 @Test public void bleedNeedsThreeRecentHitsAgainstSameTarget(){var s=new DuelCatalog.Streak();UUID a=UUID.randomUUID(),b=UUID.randomUUID();assertFalse(s.third(a,0));s.accepted(a,0);assertFalse(s.third(a,100));s.accepted(a,100);assertTrue(s.third(a,200));s.accepted(b,200);assertFalse(s.third(a,300));assertFalse(s.third(b,300));s.accepted(b,300);assertTrue(s.third(b,400));assertFalse(s.third(b,6301));s.consume();assertFalse(s.third(b,400));}
 @Test public void rangedAndDefensiveTriggersCannotBeUsedForUnrelatedHits(){assertFalse(DuelCatalog.condition("fractura",false,false,0,false,1));assertTrue(DuelCatalog.condition("fractura",false,true,0,false,1));assertFalse(DuelCatalog.condition("ocaso",true,false,143,false,1));assertTrue(DuelCatalog.condition("ocaso",true,false,144,false,1));assertFalse(DuelCatalog.condition("quitina",true,false,0,false,1));assertFalse(DuelCatalog.condition("cadenas",false,false,0,false,1));assertTrue(DuelCatalog.condition("cadenas",false,false,0,true,1));assertFalse(DuelCatalog.condition("espectral",false,false,0,false,.41));assertTrue(DuelCatalog.condition("espectral",false,false,0,false,.4));}
 @Test public void mitigationAndCooldownsStayBounded(){assertEquals(.96,DuelCatalog.multiplier("fractura")*DuelCatalog.multiplier("quitina"),.000001);assertEquals(.8,DuelCatalog.multiplier("vigia"),0);assertFalse(DuelCatalog.ready(9999,10000));assertTrue(DuelCatalog.ready(10000,10000));assertFalse(DuelCatalog.validHit(true,10));assertFalse(DuelCatalog.validHit(false,0));assertFalse(DuelCatalog.validHit(false,Double.NaN));assertFalse(DuelCatalog.validHit(false,Double.POSITIVE_INFINITY));assertTrue(DuelCatalog.validHit(false,1));}
}
